import{_ as i,a0 as n,w as s,s as a,ao as u,I as S,x as e,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"戴文的Linux內核專題：16 配置內核 (12) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：16 配置內核 (12) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：16 配置內核 (12) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：16 配置內核 (12) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/16 The Linux Kernel--Configuring the Kernel Part 12","title":"戴文的Linux內核專題：16 配置內核 (12)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/16 The Linux Kernel--Configuring the Kernel Part 12.md","filePath":"[post].md"}'),l={name:"The Linux Kernel/16 The Linux Kernel--Configuring the Kernel Part 12.md"};function C(A,t,I,T,d,M){const r=n("Link");return s(),a("div",null,[t[11]||(t[11]=u('<h1 id="戴文的linux內核專題-16-配置內核-12" tabindex="-1">戴文的Linux內核專題：16 配置內核 (12) <a class="header-anchor" href="#戴文的linux內核專題-16-配置內核-12" aria-label="Permalink to “戴文的Linux內核專題：16 配置內核 (12)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.539/" alt=""></p><p>歡迎來享受Linux內核配置系列下一部分。如你所猜到的那樣，內核支持大量不同的硬件、協議和特性。</p><p>下一組我們要討論的特性是&quot;EEPROM support&quot;。電可擦除可編程只讀存儲器(Electrically Erasable Programmable Read-Only Memory)是一種掉電或者意外關閉後不會擦除內容的存儲器。</p><p>內核支持在I2C卡上的EEPROM芯片包括FRAMs、ROMs和SRAMs (I2C EEPROMs / RAMs / ROMs 來自多數供貨商)。FRAM(同樣也稱作FeRAM是一種使用鐵電原理而不是電介質存儲數據的隨機訪問存儲芯片)。ROM芯片是隻讀(Read Only Memory)芯片。SRAM是靜態而不是動態存儲器就像DRAM。DRAN必須被刷新以保留數據而SRAM不需要刷新。然而，兩者都會在電源關閉或者丟失時失去數據。</p><p>內核支持SPI總線的EEPROM(SPI EEPROMs from most vendors)。串行外設接口總線(Serial Peripheral Interface Bus (SPI))是一個缺乏錯誤檢測的全雙工總線系統。</p><p>老式的I2C EEPROM芯片需要一個除了上面I2C驅動之外的驅動(Old I2C EEPROM reader)。I2C總線用於嵌入式系統和電話，由於它用的是低速總線協議。</p><p>這個特性用來防止Maxim的可編程EEPROM變成只讀模式(Maxim MAX6874/5 power supply supervisor)。特別地，這驅動提供對這個芯片的更好的電源管理。</p><p>這裏還有一個驅動&quot;EEPROM 93CX6 support&quot;，&quot;Microwire EEPROM 93XX46 support&quot;和&quot;ENE CB710/720 Flash memory card reader support&quot;。</p><p>和其他內核特性一樣，這裏有一個對於EEPROM的調試特性(Enable driver debugging)。再説一次，為了更好的性能，禁用調試特性。</p><p>下面，我們有一個TI特性(Shared transport core driver)。這個驅動提供對於BT/FM和GPS芯片的傳輸協議。</p><p>下面的驅動支持I2C LIS3LV02Dx加速度計(STMicroeletronics LIS3LV02Dx three-axis digital accelerometer (I2C))。設備提供的數據存儲在/sys/devices/platform/lis3lv02d。</p><p>下一步， Linux提供了下載固件到Altera的FPGA的模組(Altera FPGA firmware download module)。FPGA就是現場可編輯邏輯門陣列(field-programmable gate array)。它們是可編程集成電路。</p><p>Intel Management Engine Interface提供Intel芯片的安全和其他服務。</p><p>&quot;ME Enabled Intel Chipsets&quot;可以支持MEI。MEI是&quot;Management Engine Interface&quot;(管理引擎接口)。這個驅動支持有MEI服務的芯片組。</p><p>&quot;VMware VMCI Driver&quot;是一種用於客户機和宿主機中繼通信的高速虛擬設備。VMCI代表的是&quot;Virtual Machine Communication Interface&quot;(虛擬機通信接口)。</p><p>下面， &quot;ATA/ATAPI/MFM/RLL support&quot;可以啓用/禁用。MFM (Modified Frequency Modulation)是一種特殊的編碼軟驅位的方法。然而，這並不工作在所有的軟驅上。MFM使用RLL(Run-Length Limited)編碼制式。RLL通過有帶寬限制的系統通信轉換數據。ATAPI是先前提過的&quot;ATA Packet Interface&quot;，同時ATA也在討論接口標準的時候討論過。</p><p>現在我們將討論SCSI支持。小型計算機接口(Small Computer System Interface (SCSI))是另外一種SATA的接口標準。USB和火線設備使用SCSI協議。</p><p>第一個SCSI設定關於&quot;RAID Transport Class&quot;。這允許RAID使用SCSI標準。</p><p>為了使用SCSI目標，啓用這個特性(SCSI target support)。</p><p>如果系統會運行舊的Linux應用，系統可能需要&quot;legacy /proc/scsi/ support&quot;。這會在/proc/scsi創建SCSI文件。</p><p>為了支持SCSI磁盤，啓用下一個特性(SCSI disk support)。這是一個通用驅動。</p><p>為了支持SCSI磁帶，啓用這個特性(SCSI tape support)。這是一個通用驅動。SCSI磁帶驅動器在像磁帶的磁性條上記錄數據。</p><p>OnStream SCSI磁帶需要這個驅動而不是前面提到SCSI通用驅動SCSI OnStream SC-x0 tape support)。</p><p>&quot;對於SCSI CDROM support&quot;，一些CD-ROM使用SCSI協議。</p><p>下面， 用户可以啓用&quot;Enable vendor-specific extensions (for SCSI CDROM)&quot;。</p><p>這是一個對於大量不同SCSI設備的通用驅動(SCSI generic support)。這主要用於SCSI掃描儀和其他不被上面提到的SCSI驅動支持的設備或者那些之後會討論的設備。</p><p>一些SCSI點唱機需要這個SCSI驅動(SCSI media changer support)。</p><p>Linux內核提供&quot;SCSI Enclosure Support&quot;。SCSI附件是一種管理電源和製冷SCSI設備同時提供不關於數據的服務的設備。</p><p>Linux內核應該設置為每個SCSI設備搜索全部的邏輯單元號(Logical Unit Numbers (LUN))(Probe all LUNs on each SCSI device)。LUN是SCSI地址。</p><p>這有額外的對於SCSI的錯誤報告(Verbose SCSI error reporting (kernel size +=12K))。這會明顯地增加內核的大小。</p><p>這裏還有一個SCSI日誌系統(SCSI logging facility)。</p><p>為了增強你的系統，啓用這個特性會允許SCSI在系統啓動時就被探測到而不是先啓用再探測(Asynchronous SCSI scanning)。大多數系統可以一次執行這兩個任務，因此為什麼允許這項? 對於那些連接了很多SCSI設備的硬件，這個會明顯加快啓動速度。</p><p>下面，&quot;Parallel SCSI (SPI) Transport Attributes&quot;(傳統的並行SCSI)允許每個SCSI設備發送傳輸信息給sysfs。一些系統需要這個特性。</p><p>下面的特性和上面提到的一樣，但是發送光纖通道設備的傳輸信息(FiberChannel Transport Attributes)(光纖通道接口)。光線通道設備使用SCSI。</p><p>下面用户可以啓用/禁用&quot;SCSI target support for FiberChannel Transport Attributes&quot;(為光纖通道添加&quot;target&quot;模式驅動)。</p><p>iSCSI設備和SAS設備的傳輸數據可以導出到sysfs(iSCSI Transport Attributes)和SAS Transport Attributes)。SAS代表的的是&quot;Serial Attached SCSI&quot;(串行鏈接SCSI)。</p><p>下面，ATA支持被加入libsas(ATA support for libsas (requires libata))。注意配置工具提示需要libata。為了滿足這個需求，啓用ATA支持。更多情況下，配置工具已經或者將會會你這麼做，但是請無論再檢查一下。libsas和libata是相應的支持SAS和ATA的庫。</p><p>下面的特性允許SAS接口接收SMP幀(Support for SMP interpretation for SAS hosts)。這加入了一個SMP解釋器到libsas中。然而，這不會增加內核的尺寸。SMP幀允許所有在多CPU系統上的處理器訪問SAS設備。</p><p>SRP可以發送傳輸的數據給sysfs(SRP Transport Attributes)。SRP代表SCSI RDMA協議(SCSI RDMA Protocol)。RDMA代表遠程直接內存訪問(Remote Direct Memory Access)。這意味着SRP是一個用來訪問連接到另外一台計算機的SCSI設備的數據的協議。</p><p>下一步，用户可以啓用&quot;SCSI target support for SRP Transport&quot;。</p><p>可以啓用底層SCSI驅動(SCSI low-level drivers)。這提供了很多基礎驅動。</p><p>在這之後，用户可以啓用/禁用&quot;PCMCIA SCSI adapter support&quot;。這個適配器允許SCSI設備連接到PC卡上。</p><p>這裏有一些驅動用於特殊的適配器- (Future Domain PCMCIA support)、(Qlogic PCMCIA support) 、(Symbios 53c500 PCMCIA support)。</p><p>多路徑安裝的設備需要這個特性(SCSI Device Handlers)。這用在每個節點都需要一個到SCSI存儲單元的直接路徑的集羣中。</p><p>下一步，&quot;OSD-Initiator library&quot;(OSD啓動庫)可以啓用。這是一個提供了補丁、OSD協議、和針對SCSI設備的T10協議的SCSI驅動。 OSD代表的是基於對象的存儲設備(Object-based Storage Device);下一段會討論得更多。</p><p>這個特性生成一個SCSI上層用於測試和管理/dev/osdx設備(OSD Upper Level driver)。exofs使用這個驅動用於掛載基於OSD的文件系統。OSD設備不像其他存儲單元一樣使用塊的存儲設備。相反地，OSD設備存儲數據在稱之為對象的容器裏。exofs曾經稱作OSDFS。</p><p>如果啓用了它，OSD特性提供了調試工具(Compile All OSD modules with lots of DEBUG prints)。</p><p>如今，我們可以討論串行ATA和並行ATA特性和驅動了。首先啓用/禁用用於調試的第一個特性(Verbose ATA error reporting)。</p><p>下一步，用户應該對於ATA設備啓用高級配置及電源接口特性(ATA ACPI Support)。這允許內核在SATA設備上更有效地管理電源使用。</p><p>內核包含了對於&quot;SATA Zero Power Optical Disc Drive (ZPODD) support&quot;的驅動。這會在不使用時關閉SATA光盤驅動器(SATA optical disc drives (ODD))。這節約了能源以及減少損耗。</p><p>貼士：即使你在編譯一個高性能的內核，嘗試啓用所有的電源管理特性。則減少了電源消耗、操作開銷、熱量產生(熱量會降低性能)，以及老化。</p><p>SATA端口複用器需要這個驅動(SATA Port Multiplier support)。端口複用器是一個擁有許多端口但是自己僅需插入一個端口的設備。舉例來説，如果一個硬件有一個SATA口，但是還需要更多的口，在這個口上插入端口複用器。現在設備可以有許多SATA口了。</p><p>下一個驅動用於AHCI SATA(AHCI SATA support)。高級主機控制器接口(Advanced Host Controller Interface (AHCI))是一種SATA總線適配器的操作標準。</p><p>對於要在Soc硬件上支持AHCI SATA設備，必須啓用這個驅動(Platform AHCI SATA support)。Soc代表片上系統(System-on-a-Chip)。</p><p>下面是一些特殊設備的驅動</p><ul><li>Initio 162x SATA support</li><li>ACard AHCI variant (ATP 8620)</li><li>Silicon Image 3124/3132 SATA support</li></ul><p>再説一次，等着下一篇精彩的文章。</p><hr>',59)),S("p",null,[t[1]||(t[1]=e("via: ",-1)),p(r,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-12.4681/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-12.4681/",-1)])]),_:1})]),S("p",null,[t[4]||(t[4]=e("譯者：",-1)),p(r,{href:"https://github.com/geekpi"},{default:o(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),p(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),S("p",null,[t[8]||(t[8]=e("本文由 ",-1)),p(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),p(r,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const x=i(l,[["render",C]]);export{g as __pageData,x as default};
